const {sealObject,verifyQaReceiptBindings}=await import(pathToFileURL(join(readerRoot,'scripts/lib/release-receipt.mjs')));

const sha=v=>createHash('sha256').update(v).digest('hex');
function command(cwd,args){const r=spawnSync('git',args,{cwd,encoding:'utf8'});assert.equal(r.status,0,r.stderr);return r.stdout.trim();}
function fixture(t,kind='public'){
  const repo=realpathSync(mkdtempSync(join(tmpdir(),'qa-code-adjudication-')));t.after(()=>archiveOwnedPath(repo));mkdirSync(join(repo,'test'));
  command(repo,['init','-q']);command(repo,['config','user.email','fixture@example.invalid']);command(repo,['config','user.name','Fixture']);
  writeFileSync(join(repo,'test/ids.test.mjs'),'const idempotency_key="before";\n');
  command(repo,['add','.']);command(repo,['commit','-qm','baseline']);const base=command(repo,['rev-parse','HEAD']);
  const inputs=['public-protocol-v1','fixture-generation','workspace-id'];
  const value=kind==='public'?'p1_ingest_'+sha(inputs.map(v=>`${Buffer.byteLength(v)}:${v}`).join('')):'never retains old provider tokens in another account';
  writeFileSync(join(repo,'test/ids.test.mjs'),kind==='public'?`const idempotency_key="${value}";\n`:`test('${value}',()=>{});\n`);
  writeFileSync(join(repo,'public-metadata.json'),JSON.stringify({inputs})+'\n');command(repo,['add','.']);command(repo,['commit','-qm','candidate']);
  const head=command(repo,['rev-parse','HEAD']),file='test/ids.test.mjs';
  const raw=[{File:file,StartLine:1,RuleID:'generic-api-key',Description:'fixture scanner finding',Secret:value,Fingerprint:`${file}:generic-api-key:1`}];
  const reportPath=join(repo,'report.json');writeFileSync(reportPath,JSON.stringify(raw)+'\n');
  const binding=(name,line=1)=>({file:name,blob_sha256:sha(readFileSync(join(repo,name))),line,line_sha256:sha(readFileSync(join(repo,name),'utf8').split('\n')[line-1])});
  const row={reportIndex:0,fingerprint:raw[0].Fingerprint,finding_sha256:secretFindingHash(raw[0]),...binding(file),blob_oid:command(repo,['rev-parse',`${head}:${file}`]),classification:kind==='public'?'public_deterministic_id':'nonassigned_test_prose',rationale:'Independent source metadata proves the exact noncredential test fixture.',evidence:[binding('public-metadata.json')]};
  if(kind==='public')row.oracle={encoding:'utf8-length-prefix-sha256',prefix:'p1_ingest_',inputs};
  const decision={schema:ADJUDICATION_SCHEMA,repo,base,head,report_sha256:sha(readFileSync(reportPath)),findings:[row]};
  const options={repo,base,head,reportPath,reportSha256:decision.report_sha256,decision};
  return {repo,base,head,raw,value,reportPath,decision,row,options,binding,check:()=>evaluateSecretAdjudication(options)};
}
test('pinned deterministic public IDs and non-assigned test prose calculate benign status; no approval is fabricated',t=>{
  for(const kind of ['public','prose']){const f=fixture(t,kind),result=f.check();assert.equal(result.status,'pass');assert.equal(result.findings.length,1);assert.equal(result.findings[0].blocking,false);assert.equal(result.findings[0].applicable,true);assert.equal(result.review,undefined);}
});
test('real gitleaks report remains FAIL and its exact public finding is accounted without changing source',t=>{
  const binary=process.env.QA_CODE_GITLEAKS_FIXTURE_BINARY;if(!binary||!existsSync(binary)){t.skip('real scanner not supplied');return;}
  const f=fixture(t),report=join(f.repo,'real-scanner.json');
  archiveOwnedPath(f.reportPath);
  const r=spawnSync(binary,['dir',f.repo,'--no-banner','--log-level','error','--report-format','json','--report-path',report],{encoding:'utf8'});
  assert.equal(r.status,1,r.stderr);const raw=JSON.parse(readFileSync(report));assert.ok(raw.some(row=>row.File===join(f.repo,'test/ids.test.mjs')&&row.Secret===f.value));
  // Account for every real row without rewriting the raw absolute scanner path.
  const rows=raw.map((finding,index)=>{
    const file=finding.File,line=finding.StartLine;
    if(file===join(f.repo,'test/ids.test.mjs'))return {...f.row,reportIndex:index,fingerprint:finding.Fingerprint,finding_sha256:secretFindingHash(finding)};
    return null;
  });
  assert.ok(rows.every(Boolean),'unexpected real finding remains blocking and requires separate review');
  const hash=sha(readFileSync(report));const result=evaluateSecretAdjudication({...f.options,reportPath:report,reportSha256:hash,decision:{...f.decision,report_sha256:hash,findings:rows}});
  assert.equal(result.status,'pass');assert.equal(sha(readFileSync(report)),hash);assert.equal(r.status,1);
});
test('every actual or uncertain credential remains blocking',t=>{
  for(const classification of ['actual_secret','uncertain']){const f=fixture(t);f.row.classification=classification;assert.equal(f.check().status,'fail');}
});
