  f.raw[0].File='linked.env';writeFileSync(f.reportPath,JSON.stringify(f.raw));f.options.reportSha256=f.decision.report_sha256=sha(readFileSync(f.reportPath));f.row.finding_sha256=secretFindingHash(f.raw[0]);f.row.file='linked.env';assert.throws(f.check,/SOURCE_PATH/);
