test('actual English Markdown finding is eligible only as nonassigned prose outside code or HTML',t=>{
  const f=fixture(t),file='README.md',secret='disabled/missing/wrong';
  const line='Focused verification: `npm test -- src/test/sso-test-client-fence.test.ts`. Covers shared login/token binding, disabled/missing/wrong DB/ref/client/build, PKCE origin mismatch, unexpected redirect, isolated provider behavior and existing Production SSO.';
  const set=body=>{
    writeFileSync(join(f.repo,file),body);command(f.repo,['add',file]);command(f.repo,['commit','-qm','Markdown calibration']);f.options.head=f.decision.head=command(f.repo,['rev-parse','HEAD']);
    const lineNo=body.split('\n').findIndex(v=>v.includes(secret))+1;
    const raw={File:file,StartLine:lineNo,RuleID:'generic-api-key',Secret:secret,Fingerprint:`${file}:generic-api-key:${lineNo}`};writeFileSync(f.reportPath,JSON.stringify([raw]));f.options.reportSha256=f.decision.report_sha256=sha(readFileSync(f.reportPath));
    f.decision.findings=[{...f.row,...f.binding(file,lineNo),blob_oid:command(f.repo,['rev-parse',`${f.options.head}:${file}`]),reportIndex:0,fingerprint:raw.Fingerprint,finding_sha256:secretFindingHash(raw),classification:'nonassigned_prose'}];delete f.decision.findings[0].oracle;
  };
  set(line+'\n');assert.equal(f.check().status,'pass');
  for(const body of ['```text\n'+line+'\n```\n','<pre>\n'+line+'\n</pre>\n','    '+line+'\n','The current access_token='+secret+' is an assigned credential value in this fixture.\n','The example `'+secret+'` is inside code and is never eligible as ordinary prose.\n']){set(body);assert.equal(f.check().status,'fail');}
});
