test('a parseable synthetic provider final decision is denied without actual independent post proof',t=>{
  const f=fixture(t),session='synthetic-review-fixture',model='fixture-model',effort='low';
  const stdout=[{type:'thread.started',thread_id:session},{type:'item.completed',item:{type:'command_execution',command:'git show HEAD:test/ids.test.mjs',exit_code:0,status:'completed'}},{type:'item.completed',item:{type:'agent_message',text:JSON.stringify(f.decision)}},{type:'turn.completed'}].map(JSON.stringify).join('\n');
  const stderr=`model: ${model}\nreasoning effort: ${effort}\n`;
  const parsed=parseProviderExecution({provider:'openai',stdout,stderr});assert.deepEqual(validateProviderExecution(parsed,{provider:'openai',model,reasoning:effort}),[]);
  const stdoutPath=join(f.repo,'synthetic.stdout'),stderrPath=join(f.repo,'synthetic.stderr');writeFileSync(stdoutPath,stdout);writeFileSync(stderrPath,stderr);
  const attestationPath=join(f.repo,'synthetic-attestation.json');writeFileSync(attestationPath,JSON.stringify({agent_id:'synthetic-reviewer',session_id:session,source:{kind:'codex-stream',path:stdoutPath,sha256:sha(stdout),stderr_path:stderrPath,stderr_sha256:sha(stderr)}}));
  const proofPath=join(f.repo,'synthetic-unapproved-proof.json');writeFileSync(proofPath,JSON.stringify({role:'executor_code',seat:{provider:'openai',model,effort},coder:{agent_id:'synthetic-coder',session_id:'synthetic-coder-session'},repo_target:{repo_root:f.repo,base_sha:f.base,head_sha:f.head},run_dir:f.repo,attestation_path:attestationPath,attestation_sha256:sha(readFileSync(attestationPath))}));
  assert.throws(()=>verifySecretAdjudication({...f.options,proofPath}),/TEAMQA_/,'fixture data never authorizes a real reviewer');
});
test('actual Gate0 keeps real scanner FAIL and private raw report when post proof is missing; manual PASS config is invalid',t=>{
  const binary=process.env.QA_CODE_GITLEAKS_FIXTURE_BINARY;assert.ok(binary&&existsSync(binary),'actual scanner required');
  const f=fixture(t),out=mkdtempSync(join(tmpdir(),'qa-code-adjudication-producer-'));t.after(()=>archiveOwnedPath(out));archiveOwnedPath(f.reportPath);
  const config=join(f.repo,'qa-code.json'),json=join(out,'gate.json');writeFileSync(config,JSON.stringify({secret:{adjudication:{proof:'missing-proof.json'}}}));
  const execute=()=>spawnSync(process.execPath,[resolve('scripts/lib/gate0.mjs'),'--repo',f.repo,'--base',f.base,'--config',config,'--json',json],{encoding:'utf8',timeout:30000,env:{...process.env,PATH:resolve(binary,'..')+':/usr/bin:/bin',NODE_TEST_CONTEXT:undefined}});
  const r=execute();assert.equal(r.status,1,r.stderr);const gate=JSON.parse(readFileSync(json));assert.equal(gate.layers.secret.status,'fail');assert.equal(gate.layers.secret.raw_scanner.status,'fail');assert.equal(gate.layers.secret.adjudication.status,'fail');assert.equal(gate.layers.secret.effective_status,undefined);
  const raw=gate.layers.secret.raw_scanner.report;assert.equal(sha(readFileSync(raw.path)),raw.sha256);assert.equal(statSync(raw.path).mode&0o777,0o600);
  writeFileSync(config,JSON.stringify({secret:{adjudication:{proof:'missing-proof.json',status:'pass'}}}));const manual=execute();assert.equal(manual.status,2);assert.match(manual.stderr,/not a decision\/status/);
});
test('manual or resealed effective PASS cannot enter verdict/receipt/engine admission',t=>{
  const f=fixture(t),gate=sealObject({schema:'qa-code/gate0/v1',status:'pass',repo:f.repo,base:f.base,commit:f.head,run_uuid:randomUUID(),created_at:new Date().toISOString(),layers:{secret:{status:'fail',effective_status:'pass',raw_scanner:{status:'fail',report:{path:f.reportPath,sha256:sha(readFileSync(f.reportPath))}},adjudication:{status:'pass'}}}});
  assert.throws(()=>verifyGate0SecretAdjudication(gate),/ADJUDICATION_/);assert.equal(ruleVGate0({verdict:'PASS-STATIC',commit:f.head},gate).verdictOut,'UNGRADED');
  assert.ok(verifyQaReceiptBindings({schema:'qa-code/receipt/v1'},{gate0:gate}).some(s=>s.startsWith('ADJUDICATION_')));
  const out=mkdtempSync(join(tmpdir(),'qa-code-adjudication-admission-'));t.after(()=>archiveOwnedPath(out));const path=join(out,'gate.json'),marker=join(out,'engine-ran');writeFileSync(path,JSON.stringify(gate));
  const engine=join(out,'engine.mjs');writeFileSync(engine,`import fs from 'node:fs';fs.writeFileSync(${JSON.stringify(marker)},'must not run');`);
  const quote=s=>"'"+s.replaceAll("'","'\\''")+"'";
  const r=spawnSync('bash',[join(readerRoot,'scripts/qa-run.sh'),'--repo',f.repo,'--mode','tools','--base',f.base,'--gate0',path,'--receipt',join(out,'receipt.json'),'--engine-cmd',`${quote(process.execPath)} ${quote(engine)}`],{encoding:'utf8',env:{...process.env,QA_CODE_NODE:process.execPath},timeout:30000});
  assert.equal(r.status,20,r.stderr);assert.equal(existsSync(marker),false);assert.match(r.stderr,/R-GATE/);
});
test('current consumers reread purported post proof and reject forged, stale source and changed raw bytes after resealing',t=>{
  for(const change of [()=>{},f=>writeFileSync(f.reportPath,JSON.stringify([{...f.raw[0],Description:'changed report'}])),f=>writeFileSync(join(f.repo,f.row.file),'const idempotency_key="changed source";\n'),f=>{command(f.repo,['commit','--allow-empty','-qm','new current HEAD']);}]){
    const f=fixture(t),calculated=f.check(),proof=join(f.repo,'forged-post-proof.json');
    writeFileSync(proof,JSON.stringify({schema:'team-qa/child-dispatch-proof/v1',repo_target:{repo_root:f.repo,base_sha:f.base,head_sha:f.head},seat:{provider:'openai',model:'gpt-6.1-sol',effort:'low'},role:'executor_code',coder:{agent_id:'fixture-coder',session_id:'fixture-session'}}));
    const saved={...calculated,review:{proof_path:proof,proof_sha256:sha(readFileSync(proof)),runtime_path:undefined}};change(f);
    const gate=sealObject({schema:'qa-code/gate0/v1',status:'pass',repo:f.repo,base:f.base,commit:f.head,run_uuid:randomUUID(),created_at:new Date().toISOString(),layers:{secret:{status:'fail',effective_status:'pass',raw_scanner:{status:'fail',report:{path:f.reportPath,sha256:calculated.report.sha256}},adjudication:saved}}});
    assert.throws(()=>verifyGate0SecretAdjudication(gate),/TEAMQA_|ADJUDICATION_/);
    assert.equal(ruleVGate0({verdict:'PASS-STATIC',commit:f.head},gate).verdictOut,'UNGRADED');
    assert.ok(verifyQaReceiptBindings({schema:'qa-code/receipt/v1'},{gate0:gate}).some(s=>s.startsWith('TEAMQA_')||s.startsWith('ADJUDICATION_')));
  }
});

// Exact public source-role fixtures; none of these SQL/receiver bodies are executed.
const sqlMaterialSources={
  "test/scoped.pg.sql": "-- Modeled provider admission; actual binding/keys/nonce SQL, transaction rolled back.\nBEGIN;\nDO $$\nDECLARE a jsonb; b jsonb; rotated jsonb; config jsonb; changed jsonb;\n  sa uuid:=gen_random_uuid(); sb uuid:=gen_random_uuid(); owner uuid:=gen_random_uuid();\n  ra uuid:=gen_random_uuid(); rb uuid:=gen_random_uuid(); request uuid;\n  ca uuid; cb uuid; old_key text; new_key text; prior_count integer; denied boolean;\nBEGIN\n  config:='{\"binding\":{\"generationId\":\"generation-v1\",\"secretRef\":\"BILLING_S2S_KEY_SCOPED_BINDING\"},\"ingest\":{\"generationId\":\"generation-v1\",\"secretRef\":\"BILLING_S2S_KEY_SCOPED_INGEST\"},\"proxy\":{\"generationId\":\"generation-v1\",\"secretRef\":\"BILLING_S2S_KEY_SCOPED_PROXY\"}}';\n  a:=billing_resolve_supply_binding_and_transport(ra,repeat('a',64),'modeled-a-'||sa,sa,'source-a',owner,'member-a','subject-a',config);\n  b:=billing_resolve_supply_binding_and_transport(rb,repeat('b',64),'modeled-b-'||sb,sb,'source-b',owner,'member-b','subject-b',config);\n  ca:=(a->>'companyId')::uuid; cb:=(b->>'companyId')::uuid;\n  IF a->>'bindingState'<>'verified' OR b->>'bindingState'<>'verified' OR ca=cb\n    OR (SELECT count(*) FROM billing_transport_keys WHERE company_id IN(ca,cb))<>6\n    OR EXISTS(SELECT 1 FROM billing_transport_keys WHERE company_id IN(ca,cb) AND\n      (key_id !~ '^p1_(binding|ingest|proxy)_[0-9a-f]{64}$' OR length(key_id)>128))\n  THEN RAISE EXCEPTION 'TWO_SCOPE_ISSUANCE_FAILED'; END IF;\n  PERFORM billing_resolve_supply_binding_and_transport(ra,repeat('a',64),'modeled-a-'||sa,sa,'source-a',owner,'member-a','subject-a',config);\n  IF (SELECT count(*) FROM billing_transport_keys WHERE company_id IN(ca,cb))<>6\n    OR (SELECT count(*) FROM billing_supply_binding_evidence WHERE request_id IN(ra,rb))<>2\n  THEN RAISE EXCEPTION 'REPLAY_CREATED_EXTRA_KEYS'; END IF;\n  old_key:=billing_supply_scoped_transport_id('generation-v1','ingest',ca,'modeled-a-'||sa,sa,a->>'identityRevision');\n  IF NOT billing_claim_transport_nonce(old_key,'nonce-a-scoped-123456789012',repeat('c',64),clock_timestamp())\n    OR billing_claim_transport_nonce(old_key,'nonce-a-scoped-123456789012',repeat('c',64),clock_timestamp())\n  THEN RAISE EXCEPTION 'NONCE_REPLAY_NOT_ISOLATED'; END IF;\n  changed:=jsonb_set(config,'{ingest,secretRef}','\"BILLING_S2S_KEY_DIFFERENT\"');\n  request:=gen_random_uuid(); denied:=false;\n  BEGIN\n    PERFORM billing_resolve_supply_binding_and_transport(request,repeat('d',64),'modeled-a-'||sa,sa,'source-a',owner,'member-a','subject-a',changed);\n  EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='TRANSPORT_KEY_REUSE_DENIED'; END;\n  IF NOT denied OR EXISTS(SELECT 1 FROM billing_supply_binding_evidence WHERE request_id=request)\n    OR (SELECT secret_ref FROM billing_transport_keys WHERE key_id=old_key)<>'BILLING_S2S_KEY_SCOPED_INGEST'\n  THEN RAISE EXCEPTION 'COLLISION_NOT_ATOMIC'; END IF;\n  UPDATE billing_transport_keys SET valid_from=clock_timestamp()+interval '1 hour' WHERE key_id=old_key;\n  request:=gen_random_uuid(); denied:=false;\n  BEGIN\n    PERFORM billing_resolve_supply_binding_and_transport(request,repeat('2',64),'modeled-a-'||sa,sa,'source-a',owner,'member-a','subject-a',config);\n  EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='TRANSPORT_KEY_REUSE_DENIED'; END;\n  IF NOT denied OR EXISTS(SELECT 1 FROM billing_supply_binding_evidence WHERE request_id=request)\n    OR billing_claim_transport_nonce(old_key,'nonce-future-scoped-123456789012',repeat('2',64),clock_timestamp())\n    OR (SELECT count(*) FROM billing_transport_keys WHERE company_id IN(ca,cb))<>6\n  THEN RAISE EXCEPTION 'FUTURE_KEY_NOT_ATOMICALLY_DENIED'; END IF;\n  UPDATE billing_transport_keys SET valid_from=(a->>'providerVerifiedAt')::timestamptz WHERE key_id=old_key;\n  rotated:=billing_resolve_supply_binding_and_transport(gen_random_uuid(),repeat('e',64),'modeled-a-'||sa,sa,'source-a-v2',owner,'member-a','subject-a',config);\n  new_key:=billing_supply_scoped_transport_id('generation-v1','ingest',ca,'modeled-a-'||sa,sa,rotated->>'identityRevision');\n  IF new_key=old_key OR (SELECT count(*) FROM billing_transport_keys WHERE company_id=ca AND revoked_at IS NOT NULL)<>3\n    OR (SELECT count(*) FROM billing_transport_keys WHERE company_id=cb AND revoked_at IS NULL)<>3\n    OR billing_claim_transport_nonce(old_key,'nonce-old-scoped-123456789012',repeat('e',64),clock_timestamp())\n  THEN RAISE EXCEPTION 'ROTATION_REBOUND_OTHER_SCOPE'; END IF;\n  UPDATE billing_transport_keys SET revoked_at=clock_timestamp() WHERE key_id=new_key;\n  denied:=false; request:=gen_random_uuid();\n  BEGIN\n    PERFORM billing_resolve_supply_binding_and_transport(request,repeat('f',64),'modeled-a-'||sa,sa,'source-a-v2',owner,'member-a','subject-a',config);\n  EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='TRANSPORT_KEY_REUSE_DENIED'; END;\n  IF NOT denied OR EXISTS(SELECT 1 FROM billing_supply_binding_evidence WHERE request_id=request)\n    OR (SELECT revoked_at FROM billing_transport_keys WHERE key_id=new_key) IS NULL\n  THEN RAISE EXCEPTION 'REVOKED_KEY_RESURRECTED'; END IF;\n  config:=replace(config::text,'generation-v1','generation-v2')::jsonb;\n  PERFORM billing_resolve_supply_binding_and_transport(gen_random_uuid(),repeat('1',64),'modeled-a-'||sa,sa,'source-a-v2',owner,'member-a','subject-a',config);\n  IF (SELECT count(*) FROM billing_transport_keys WHERE company_id=ca AND revoked_at IS NULL)<>3\n    OR (SELECT count(*) FROM billing_transport_nonces WHERE key_id=old_key)<>1\n    OR EXISTS(SELECT 1 FROM billing_invoices WHERE company_id IN(ca,cb))\n  THEN RAISE EXCEPTION 'ROTATION_ERASED_HISTORY_OR_CREATED_MONEY'; END IF;\n  IF has_function_privilege('anon','billing_resolve_supply_binding_and_transport(uuid,text,text,uuid,text,uuid,text,text,jsonb)','EXECUTE')\n    OR has_function_privilege('authenticated','billing_resolve_supply_binding_and_transport(uuid,text,text,uuid,text,uuid,text,text,jsonb)','EXECUTE')\n    OR NOT has_function_privilege('service_role','billing_resolve_supply_binding_and_transport(uuid,text,text,uuid,text,uuid,text,text,jsonb)','EXECUTE')\n  THEN RAISE EXCEPTION 'CUSTOMER_CAN_PROVISION_KEYS'; END IF;\n  RAISE NOTICE 'SCOPED_SQL_GREEN two_companies=2 initial_keys=6 replay_extra=0 collision_atomic=true future_key_denied=true rotation_isolated=true revoked_resurrection=false preserved_nonce=1 money_rows=0';\nEND $$;\nROLLBACK;\n\n\n-- Modeled provider admission; real read/ACL/nonce SQL in an isolated local clone.\nBEGIN;\nDO $$\nDECLARE a jsonb; r jsonb; k text; company uuid; workspace uuid:=gen_random_uuid();\n  denied boolean; before_nonce bigint; meta record;\nBEGIN\n  a:=public.billing_resolve_supply_binding_and_transport(gen_random_uuid(),repeat('a',64),\n    'modeled-r65-'||workspace,workspace,'source-r65',gen_random_uuid(),'member-r65','subject-r65',\n    '{\"binding\":{\"generationId\":\"r65\",\"secretRef\":\"BILLING_S2S_KEY_TEST\"},\"ingest\":{\"generationId\":\"r65\",\"secretRef\":\"BILLING_S2S_KEY_TEST\"},\"proxy\":{\"generationId\":\"r65\",\"secretRef\":\"BILLING_S2S_KEY_TEST\"}}');\n  company:=(a->>'companyId')::uuid;\n  SELECT key_id INTO k FROM public.billing_transport_keys WHERE company_id=company\n    AND 'proxy_billing_action'=ANY(allowed_actions);\n  SELECT count(*) INTO before_nonce FROM public.billing_transport_nonces;\n  SELECT p.provolatile,p.prosecdef,p.proconfig INTO meta FROM pg_catalog.pg_proc p\n    WHERE p.oid='public.billing_read_transport_key_scope(text)'::regprocedure;\n  IF meta.provolatile<>'s' OR meta.prosecdef OR meta.proconfig<>ARRAY['search_path=\"\"']\n    OR has_function_privilege('anon','public.billing_read_transport_key_scope(text)','EXECUTE')\n    OR has_function_privilege('authenticated','public.billing_read_transport_key_scope(text)','EXECUTE')\n    OR NOT has_function_privilege('service_role','public.billing_read_transport_key_scope(text)','EXECUTE')\n  THEN RAISE EXCEPTION 'READ_RPC_AUTHORITY_WIDENED'; END IF;\n  EXECUTE 'SET LOCAL ROLE service_role';\n  r:=public.billing_read_transport_key_scope(k);\n  EXECUTE 'RESET ROLE';\n  IF r->'key'->>'key_id'<>k OR r->'key'->>'company_id'<>company::text\n    OR r->'company'->>'tenant_workspace_id'<>'modeled-r65-'||workspace\n    OR r->'binding'->>'source_workspace_id'<>workspace::text\n    OR r->'binding'->>'identity_revision'<>a->>'identityRevision'\n    OR r->'binding'->>'status'<>'verified' OR (r->>'scopeUnavailable')::boolean\n    OR (SELECT count(*) FROM jsonb_object_keys(r))<>4\n    OR (SELECT count(*) FROM jsonb_object_keys(r->'key'))<>13\n    OR r::text LIKE '%SQLERRM%' OR r->'key' ? 'secret'\n    OR (SELECT count(*) FROM public.billing_transport_nonces)<>before_nonce\n  THEN RAISE EXCEPTION 'READ_RPC_METADATA_OR_SIDE_EFFECT_INVALID'; END IF;\n  r:=public.billing_read_transport_key_scope('missing-r65');\n  IF r<>jsonb_build_object('key',NULL,'company',NULL,'binding',NULL,'scopeUnavailable',false)\n  THEN RAISE EXCEPTION 'MISSING_KEY_SHAPE_INVALID'; END IF;\n  FOREACH k IN ARRAY ARRAY['anon','authenticated'] LOOP\n    denied:=false; EXECUTE 'SET LOCAL ROLE '||quote_ident(k);\n    BEGIN\n      PERFORM public.billing_read_transport_key_scope('missing-r65');\n    EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;\n    EXECUTE 'RESET ROLE';\n    IF NOT denied THEN RAISE EXCEPTION 'UNPRIVILEGED_READ_RPC_EXECUTED'; END IF;\n  END LOOP;\n  SELECT key_id INTO k FROM public.billing_transport_keys WHERE company_id=company\n    AND 'proxy_billing_action'=ANY(allowed_actions);\n  REVOKE SELECT ON public.billing_module_bindings FROM service_role;\n  EXECUTE 'SET LOCAL ROLE service_role';\n  r:=public.billing_read_transport_key_scope(k);\n  EXECUTE 'RESET ROLE';\n  GRANT SELECT ON public.billing_module_bindings TO service_role;\n  IF r->'key'->>'key_id'<>k OR NOT (r->>'scopeUnavailable')::boolean\n    OR r->'company'<>'null'::jsonb OR r->'binding'<>'null'::jsonb\n    OR r::text LIKE '%permission denied%'\n  THEN RAISE EXCEPTION 'SCOPE_SQL_ERROR_LOST_STAGED_METADATA'; END IF;\n  REVOKE SELECT ON public.billing_transport_keys FROM service_role;\n  denied:=false; EXECUTE 'SET LOCAL ROLE service_role';\n  BEGIN\n    PERFORM public.billing_read_transport_key_scope(k);\n  EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='TRANSPORT_KEY_LOOKUP_UNAVAILABLE'; END;\n  EXECUTE 'RESET ROLE';\n  GRANT SELECT ON public.billing_transport_keys TO service_role;\n  IF NOT denied THEN RAISE EXCEPTION 'KEY_SQL_ERROR_STAGE_CHANGED'; END IF;\n  UPDATE public.billing_transport_keys SET revoked_at=clock_timestamp() WHERE key_id=k;\n  r:=public.billing_read_transport_key_scope(k);\n  IF r->'key'->>'revoked_at' IS NULL OR public.billing_claim_transport_nonce(\n    k,'nonce-revoked-r65-123456789012',repeat('b',64),clock_timestamp())\n  THEN RAISE EXCEPTION 'REVOKED_METADATA_OR_NONCE_ADMITTED'; END IF;\n  UPDATE public.billing_transport_keys SET revoked_at=NULL,\n    valid_from=clock_timestamp()+interval '1 hour' WHERE key_id=k;\n  IF public.billing_claim_transport_nonce(k,'nonce-future-r65-123456789012',repeat('b',64),clock_timestamp())\n  THEN RAISE EXCEPTION 'FUTURE_NONCE_ADMITTED'; END IF;\n  UPDATE public.billing_transport_keys SET valid_from=clock_timestamp()-interval '2 hours',\n    valid_until=clock_timestamp()-interval '1 hour' WHERE key_id=k;\n  IF public.billing_claim_transport_nonce(k,'nonce-expired-r65-123456789012',repeat('b',64),clock_timestamp())\n  THEN RAISE EXCEPTION 'EXPIRED_NONCE_ADMITTED'; END IF;\n  UPDATE public.billing_transport_keys SET valid_until=NULL WHERE key_id=k;\n  UPDATE public.billing_module_bindings SET status='stale' WHERE company_id=company AND module='supply';\n  r:=public.billing_read_transport_key_scope(k);\n  IF r->'binding'->>'status'<>'stale' OR public.billing_claim_transport_nonce(\n    k,'nonce-stale-r65-123456789012',repeat('b',64),clock_timestamp())\n  THEN RAISE EXCEPTION 'STALE_BINDING_NONCE_ADMITTED'; END IF;\n  RAISE NOTICE 'READ_RPC_NATIVE_GREEN real_acl=true invoker=true stable=true metadata_only=true key_scope_errors_distinct=true revoked_future_expired_stale_nonce_denied=true';\nEND $$;\nROLLBACK;\n",
  "resolver.sql": "-- Automatic scoped metadata; secret bytes remain in purpose-specific server envs.\nBEGIN;\nCREATE OR REPLACE FUNCTION public.billing_supply_scoped_transport_id(\n  p_generation text,p_purpose text,p_company_id uuid,p_provider_workspace_id text,\n  p_source_workspace_id uuid,p_identity_revision text\n) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$\nDECLARE value text; canonical text:='';\nBEGIN\n  IF p_generation IS NULL OR p_generation !~ '^[A-Za-z0-9_-]{1,128}$'\n    OR p_purpose IS NULL OR p_purpose NOT IN ('binding','ingest','proxy')\n    OR p_company_id IS NULL OR p_source_workspace_id IS NULL\n    OR p_provider_workspace_id IS NULL OR length(p_provider_workspace_id) NOT BETWEEN 1 AND 256\n    OR p_identity_revision IS NULL OR length(p_identity_revision) NOT BETWEEN 1 AND 256\n  THEN RAISE EXCEPTION 'TRANSPORT_SCOPE_INVALID'; END IF;\n  FOREACH value IN ARRAY ARRAY['billing-transport-scope-v1',p_generation,p_purpose,\n    p_company_id::text,'https://auth.example.invalid',p_provider_workspace_id,\n    p_source_workspace_id::text,p_identity_revision]\n  LOOP canonical:=canonical||octet_length(value)::text||':'||value; END LOOP;\n  RETURN 'p1_'||p_purpose||'_'||pg_catalog.encode(pg_catalog.sha256(\n    pg_catalog.convert_to(canonical,'UTF8')),'hex');\nEND $$;\nREVOKE ALL ON FUNCTION public.billing_supply_scoped_transport_id(text,text,uuid,text,uuid,text)\n  FROM PUBLIC,anon,authenticated;\nGRANT EXECUTE ON FUNCTION public.billing_supply_scoped_transport_id(text,text,uuid,text,uuid,text) TO service_role;\n\nCREATE OR REPLACE FUNCTION public.billing_resolve_supply_binding_and_transport(\n  p_request_id uuid,p_body_sha256 text,p_provider_workspace_id text,\n  p_source_workspace_id uuid,p_source_identity_revision text,p_local_owner_id uuid,\n  p_owner_membership_revision text,p_provider_subject text,p_key_config jsonb\n) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$\nDECLARE result jsonb; purpose text; config jsonb; v_key_id text; keys text[]:=ARRAY[]::text[];\n  existing public.billing_transport_keys; actions text[]; v_company_id uuid; revision text;\nBEGIN\n  IF p_key_config IS NULL OR jsonb_typeof(p_key_config)<>'object'\n    OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_key_config) k)\n      IS DISTINCT FROM ARRAY['binding','ingest','proxy']::text[]\n  THEN RAISE EXCEPTION 'TRANSPORT_CONFIG_INVALID'; END IF;\n  FOREACH purpose IN ARRAY ARRAY['binding','ingest','proxy'] LOOP\n    config:=p_key_config->purpose;\n    IF jsonb_typeof(config)<>'object'\n      OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(config) k)\n        IS DISTINCT FROM ARRAY['generationId','secretRef']::text[]\n      OR config->>'generationId' IS NULL OR config->>'generationId' !~ '^[A-Za-z0-9_-]{1,128}$'\n      OR config->>'secretRef' IS NULL OR config->>'secretRef' !~ '^BILLING_S2S_KEY_[A-Z0-9_]{1,80}$'\n    THEN RAISE EXCEPTION 'TRANSPORT_CONFIG_INVALID'; END IF;\n  END LOOP;\n  -- The Edge gateway already established fresh provider/current-owner proof.\n  -- Existing resolver locks source/company and refuses conflicts or revocations.\n  result:=public.billing_resolve_supply_binding(p_request_id,p_body_sha256,\n    p_provider_workspace_id,p_source_workspace_id,p_source_identity_revision,\n    p_local_owner_id,p_owner_membership_revision,p_provider_subject);\n  IF result->>'bindingState'<>'verified' THEN RETURN result; END IF;\n  v_company_id:=(result->>'companyId')::uuid; revision:=result->>'identityRevision';\n  FOREACH purpose IN ARRAY ARRAY['binding','ingest','proxy'] LOOP\n    config:=p_key_config->purpose;\n    v_key_id:=public.billing_supply_scoped_transport_id(config->>'generationId',purpose,\n      v_company_id,p_provider_workspace_id,p_source_workspace_id,revision);\n    keys:=array_append(keys,v_key_id);\n    actions:=CASE purpose WHEN 'ingest' THEN ARRAY['ingest_supply_usage']\n      ELSE ARRAY['proxy_billing_action'] END;\n    -- Proxy uses a fresh signed binding READ before late/customer operations.\n    SELECT * INTO existing FROM public.billing_transport_keys k WHERE k.key_id=v_key_id FOR UPDATE;\n    IF FOUND THEN\n      IF existing.revoked_at IS NOT NULL OR existing.valid_until<=clock_timestamp()\n        OR existing.valid_from>clock_timestamp()\n        OR existing.company_id<>v_company_id OR existing.provider_issuer<>'https://auth.example.invalid'\n        OR existing.provider_workspace_id<>p_provider_workspace_id\n        OR existing.source_workspace_id<>p_source_workspace_id::text\n        OR existing.identity_revision<>revision OR existing.secret_ref<>config->>'secretRef'\n        OR existing.sender<>'supply' OR existing.audience<>'hrm-billing'\n        OR existing.allowed_actions IS DISTINCT FROM actions\n      THEN RAISE EXCEPTION 'TRANSPORT_KEY_REUSE_DENIED'; END IF;\n    ELSE\n      INSERT INTO public.billing_transport_keys(key_id,company_id,provider_issuer,\n        provider_workspace_id,source_workspace_id,identity_revision,secret_ref,\n        sender,audience,allowed_actions,valid_from)\n      VALUES(v_key_id,v_company_id,'https://auth.example.invalid',p_provider_workspace_id,\n        p_source_workspace_id::text,revision,config->>'secretRef','supply','hrm-billing',actions,(result->>'providerVerifiedAt')::timestamptz);\n    END IF;\n  END LOOP;\n  UPDATE public.billing_transport_keys k SET revoked_at=clock_timestamp()\n    WHERE k.company_id=v_company_id AND k.source_workspace_id=p_source_workspace_id::text\n      AND k.sender='supply' AND k.audience='hrm-billing' AND k.key_id LIKE 'p1\\_%' ESCAPE '\\'\n      AND NOT (k.key_id=ANY(keys)) AND k.revoked_at IS NULL;\n  RETURN result;\nEND $$;\nREVOKE ALL ON FUNCTION public.billing_resolve_supply_binding_and_transport(uuid,text,text,uuid,text,uuid,text,text,jsonb)\n  FROM PUBLIC,anon,authenticated;\nGRANT EXECUTE ON FUNCTION public.billing_resolve_supply_binding_and_transport(uuid,text,text,uuid,text,uuid,text,text,jsonb) TO service_role;\nCOMMIT;\n",
  "transport.sql": "-- Billing server-to-server transport metadata and durable nonce claim. No key secret stored here.\n-- Offline authoring only until isolated Test target and signing secret are released.\nCREATE TABLE public.billing_transport_keys (\n  key_id text PRIMARY KEY CHECK (length(key_id) BETWEEN 1 AND 128),\n  company_id uuid NOT NULL REFERENCES public.billing_companies(id) ON DELETE RESTRICT,\n  provider_issuer text NOT NULL CHECK (provider_issuer='https://auth.example.invalid'),\n  provider_workspace_id text NOT NULL,\n  source_workspace_id text NOT NULL,\n  identity_revision text NOT NULL,\n  secret_ref text NOT NULL, -- Environment/KMS reference only, never raw key bytes.\n  sender text NOT NULL CHECK (sender='supply'),\n  audience text NOT NULL CHECK (audience='hrm-billing'),\n  allowed_actions text[] NOT NULL CHECK (allowed_actions <@ ARRAY['ingest_supply_usage','proxy_billing_action']::text[]),\n  valid_from timestamptz NOT NULL,\n  valid_until timestamptz,\n  revoked_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  CHECK (valid_until IS NULL OR valid_until>valid_from)\n);\nCREATE TABLE public.billing_transport_nonces (\n  key_id text NOT NULL REFERENCES public.billing_transport_keys(key_id) ON DELETE RESTRICT,\n  nonce text NOT NULL CHECK (length(nonce) BETWEEN 22 AND 128),\n  body_sha256 text NOT NULL CHECK (length(body_sha256)=64),\n  sent_at timestamptz NOT NULL,\n  expires_at timestamptz NOT NULL,\n  claimed_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (key_id,nonce),\n  CHECK (expires_at = sent_at + interval '300 seconds')\n);\nCREATE INDEX billing_transport_nonce_expiry_idx ON public.billing_transport_nonces(expires_at);\nALTER TABLE public.billing_transport_keys ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.billing_transport_nonces ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON public.billing_transport_keys, public.billing_transport_nonces FROM PUBLIC,anon,authenticated;\nGRANT SELECT,INSERT,UPDATE ON public.billing_transport_keys TO service_role;\nGRANT SELECT,INSERT ON public.billing_transport_nonces TO service_role;\n\nCREATE FUNCTION public.billing_claim_transport_nonce(\n  p_key_id text, p_nonce text, p_body_sha256 text, p_sent_at timestamptz\n) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$\nDECLARE inserted integer;\nBEGIN\n  IF p_nonce IS NULL OR length(p_nonce) NOT BETWEEN 22 AND 128\n    OR p_body_sha256 IS NULL OR length(p_body_sha256)<>64 OR p_sent_at IS NULL\n    OR abs(extract(epoch FROM (now()-p_sent_at)))>300 THEN\n    RETURN false;\n  END IF;\n  IF NOT EXISTS (\n    SELECT 1 FROM public.billing_transport_keys k\n    JOIN public.billing_module_bindings b ON b.company_id=k.company_id AND b.module='supply'\n    JOIN public.billing_companies c ON c.id=k.company_id\n    WHERE k.key_id=p_key_id AND k.revoked_at IS NULL AND k.valid_from<=now()\n      AND (k.valid_until IS NULL OR now()<k.valid_until)\n      AND b.status='verified' AND b.identity_revision=k.identity_revision\n      AND b.source_workspace_id=k.source_workspace_id\n      AND c.issuer=k.provider_issuer AND c.tenant_workspace_id=k.provider_workspace_id\n  ) THEN RETURN false; END IF;\n  INSERT INTO public.billing_transport_nonces(key_id,nonce,body_sha256,sent_at,expires_at)\n    VALUES(p_key_id,p_nonce,p_body_sha256,p_sent_at,p_sent_at + interval '300 seconds')\n    ON CONFLICT DO NOTHING;\n  GET DIAGNOSTICS inserted=ROW_COUNT;\n  RETURN inserted=1;\nEND;\n$$;\nREVOKE ALL ON FUNCTION public.billing_claim_transport_nonce(text,text,text,timestamptz)\n  FROM PUBLIC,anon,authenticated;\nGRANT EXECUTE ON FUNCTION public.billing_claim_transport_nonce(text,text,text,timestamptz)\n  TO service_role;\nCREATE TRIGGER billing_transport_nonce_immutable BEFORE UPDATE OR DELETE ON public.billing_transport_nonces\nFOR EACH ROW EXECUTE FUNCTION public.billing_reject_mutation();\n\nCREATE FUNCTION public.billing_validate_transport_key_scope() RETURNS trigger\nLANGUAGE plpgsql SET search_path='' AS $$\nBEGIN\n  IF TG_OP='INSERT' THEN\n    IF NOT EXISTS (\n    SELECT 1 FROM public.billing_companies c\n    JOIN public.billing_module_bindings b ON b.company_id=c.id AND b.module='supply'\n    WHERE c.id=NEW.company_id AND c.issuer=NEW.provider_issuer\n      AND c.tenant_workspace_id=NEW.provider_workspace_id\n      AND b.source_workspace_id=NEW.source_workspace_id\n      AND b.identity_revision=NEW.identity_revision AND b.status='verified'\n    ) THEN RAISE EXCEPTION 'BILLING_TRANSPORT_SCOPE_INVALID'; END IF;\n  END IF;\n  IF TG_OP='UPDATE' AND (NEW.company_id IS DISTINCT FROM OLD.company_id\n    OR NEW.provider_issuer IS DISTINCT FROM OLD.provider_issuer\n    OR NEW.provider_workspace_id IS DISTINCT FROM OLD.provider_workspace_id\n    OR NEW.source_workspace_id IS DISTINCT FROM OLD.source_workspace_id\n    OR NEW.identity_revision IS DISTINCT FROM OLD.identity_revision\n    OR NEW.secret_ref IS DISTINCT FROM OLD.secret_ref) THEN\n    RAISE EXCEPTION 'BILLING_TRANSPORT_KEY_SCOPE_IMMUTABLE';\n  END IF;\n  RETURN NEW;\nEND;\n$$;\nCREATE TRIGGER billing_transport_key_scope_guard BEFORE INSERT OR UPDATE ON public.billing_transport_keys\nFOR EACH ROW EXECUTE FUNCTION public.billing_validate_transport_key_scope();\n",
  "receiver.ts": "import { phase1RuntimeDisabled } from '../_shared/billing-phase1-runtime.ts';\nimport { createClient } from 'https://esm.sh/@supabase/supabase-js@2.95.2'\nimport { BILLING_S2S_CLOCK_SKEW_MS, verifyBillingRequest,\n  type BillingSignedHeaders, type BillingSigningScope } from '../_shared/billing-signature.ts'\nimport { validateSupplyIngest } from '../../../src/lib/billing-domain/supply-ingest-contract.ts'\nimport type { CompanyId, SourceWorkspaceId } from '../../../src/lib/billing-domain/identifiers.ts'\nimport { BoundedJsonBodyError, readBoundedBody } from '../_shared/billing-bounded-json-body.ts'\nimport { fetchSupplyNativeProof } from '../_shared/billing-supply-native-proof/client.ts'\nimport { readPhase1ProductionRuntime } from '../_shared/billing-phase1-runtime.ts'\n\nconst COMPANY_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i\nfunction validTrustedIds(value: { companyId: unknown; sourceWorkspaceId: unknown }):\n  value is { companyId: CompanyId; sourceWorkspaceId: SourceWorkspaceId } {\n  return typeof value.companyId === 'string' && COMPANY_UUID.test(value.companyId)\n    && typeof value.sourceWorkspaceId === 'string'\n    && Array.from(value.sourceWorkspaceId).length >= 1\n    && Array.from(value.sourceWorkspaceId).length <= 256\n}\n\nconst response = (body: unknown, status = 200) => new Response(JSON.stringify(body), {\n  status, headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' },\n})\nconst failure = (code: string, status: number) => response({ ok: false, code }, status)\nconst HEADER_NAMES = {\n  keyId: 'X-Example-Billing-Key-Id', sender: 'X-Example-Billing-Sender',\n  audience: 'X-Example-Billing-Audience', action: 'X-Example-Billing-Action',\n  timestamp: 'X-Example-Billing-Timestamp', nonce: 'X-Example-Billing-Nonce',\n  bodySha256: 'X-Example-Billing-Body-Sha256', signature: 'X-Example-Billing-Signature',\n} as const\n\nfunction signedHeaders(headers: Headers): BillingSignedHeaders | null {\n  const fields = Object.fromEntries(Object.entries(HEADER_NAMES).map(([key, name]) =>\n    [key, headers.get(name)])) as Record<keyof BillingSignedHeaders, string | null>\n  if (Object.values(fields).some(value => !value || value.length > 256)) return null\n  if (fields.sender !== 'supply' || fields.audience !== 'hrm-billing'\n    || fields.action !== 'ingest_supply_usage') return null\n  return fields as BillingSignedHeaders\n}\n\nfunction secretBytes(secretRef: string): Uint8Array | null {\n  if (!/^BILLING_S2S_KEY_[A-Z0-9_]{1,80}$/.test(secretRef)) return null\n  const encoded = Deno.env.get(secretRef)\n  if (!encoded || !/^[A-Za-z0-9_-]+$/.test(encoded)) return null\n  try {\n    const raw = atob(encoded.replace(/-/g, '+').replace(/_/g, '/')\n      + '='.repeat((4 - encoded.length % 4) % 4))\n    const bytes = Uint8Array.from(raw, c => c.charCodeAt(0))\n    return bytes.byteLength >= 32 ? bytes : null\n  } catch { return null }\n}\n\nDeno.serve(async req => {\n  if (req.method !== 'POST') return failure('METHOD_NOT_ALLOWED', 405)\n  if (phase1RuntimeDisabled(name => Deno.env.get(name), 'hrm')) return failure('PHASE1_RUNTIME_DISABLED', 503);\n  const headers = signedHeaders(req.headers)\n  if (!headers) return failure('SIGNED_HEADERS_REQUIRED', 401)\n  let rawBody: string\n  try { rawBody = new TextDecoder().decode(await readBoundedBody(req, 262144)) }\n  catch (error) {\n    return error instanceof BoundedJsonBodyError && error.reason === 'too_large'\n      ? failure('BODY_TOO_LARGE', 413) : failure('BODY_UNAVAILABLE', 400)\n  }\n  const admin = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!, {\n    auth: { autoRefreshToken: false, persistSession: false },\n  })\n  try {\n    const verified = await verifyBillingRequest(rawBody, headers, new Date().toISOString(),\n      async keyId => {\n        const { data: key, error } = await admin.from('billing_transport_keys')\n          .select('key_id,company_id,provider_issuer,provider_workspace_id,source_workspace_id,identity_revision,secret_ref,sender,audience,allowed_actions,valid_from,valid_until,revoked_at')\n          .eq('key_id', keyId).maybeSingle()\n        if (error) throw new Error('TRANSPORT_KEY_LOOKUP_UNAVAILABLE')\n        if (!key || key.sender !== 'supply' || key.audience !== 'hrm-billing'\n          || key.revoked_at || Date.parse(key.valid_from) > Date.now()\n          || key.valid_until && Date.parse(key.valid_until) <= Date.now()) return null\n        const [company, binding] = await Promise.all([\n          admin.from('billing_companies').select('issuer,tenant_workspace_id')\n            .eq('id', key.company_id).maybeSingle(),\n          admin.from('billing_module_bindings').select('status,source_workspace_id,identity_revision')\n            .eq('company_id', key.company_id).eq('module', 'supply').maybeSingle(),\n        ])\n        if (company.error || binding.error) throw new Error('TRANSPORT_SCOPE_LOOKUP_UNAVAILABLE')\n        if (!company.data || company.data.issuer !== key.provider_issuer\n          || company.data.tenant_workspace_id !== key.provider_workspace_id\n          || !binding.data || binding.data.status !== 'verified'\n          || binding.data.source_workspace_id !== key.source_workspace_id\n          || binding.data.identity_revision !== key.identity_revision) return null\n        const ids = { companyId: key.company_id, sourceWorkspaceId: key.source_workspace_id }\n        if (!validTrustedIds(ids)) throw new Error('TRANSPORT_KEY_LOOKUP_UNAVAILABLE')\n        const secret = secretBytes(key.secret_ref)\n        if (!secret) throw new Error('TRANSPORT_KEY_SECRET_UNAVAILABLE')\n        const scope: BillingSigningScope = { keyId: key.key_id, secret,\n          companyId: ids.companyId,\n          providerIssuer: key.provider_issuer, providerWorkspaceId: key.provider_workspace_id,\n          sourceWorkspaceId: ids.sourceWorkspaceId, identityRevision: key.identity_revision,\n          actions: key.allowed_actions, active: true }\n        return scope\n      },\n      async (keyId, nonce, expiresAt) => {\n        const sentAt = new Date(Date.parse(expiresAt) - BILLING_S2S_CLOCK_SKEW_MS).toISOString()\n        const { data, error } = await admin.rpc('billing_claim_transport_nonce', {\n          p_key_id: keyId, p_nonce: nonce, p_body_sha256: headers.bodySha256, p_sent_at: sentAt,\n        })\n        if (error) throw new Error('TRANSPORT_NONCE_UNAVAILABLE')\n        return data === true\n      })\n    if (!validTrustedIds(verified.scope)) throw new Error('TRANSPORT_KEY_LOOKUP_UNAVAILABLE')\n    let parsed: unknown\n    try { parsed = JSON.parse(rawBody) } catch { return failure('INVALID_ENVELOPE', 400) }\n    const decision = validateSupplyIngest(parsed, {\n      authenticatedServiceId: verified.scope.keyId,\n      authenticatedCompanyId: verified.scope.companyId,\n      authenticatedIssuer: verified.scope.providerIssuer,\n      authenticatedProviderWorkspaceId: verified.scope.providerWorkspaceId,\n      authenticatedWorkspaceId: verified.scope.sourceWorkspaceId,\n      authenticatedIdentityRevision: verified.scope.identityRevision,\n      signatureVerified: true, requestSentAt: verified.requestSentAt,\n      receivedAt: new Date().toISOString(), maxClockSkewMs: BILLING_S2S_CLOCK_SKEW_MS,\n    })\n    if (!decision.ok) return failure(decision.reason, 409)\n    let nativeProof = null\n    if (decision.envelope.kind === 'source_event') {\n      try {\n        nativeProof = await fetchSupplyNativeProof(decision.envelope, headers.bodySha256, {\n          url: Deno.env.get('BILLING_SUPPLY_SOURCE_PROOF_URL'),\n          keyId: Deno.env.get('BILLING_SUPPLY_SOURCE_PROOF_KEY_ID'),\n          keyBase64: Deno.env.get('BILLING_SUPPLY_SOURCE_PROOF_KEY_BASE64'),\n          production: readPhase1ProductionRuntime(name => Deno.env.get(name)),\n        })\n      } catch {\n        return failure('SOURCE_PROOF_UNAVAILABLE', 503)\n      }\n    }\n    const { data: ack, error } = await admin.rpc('billing_ingest_supply_envelope', {\n      p_key_id: headers.keyId, p_envelope: decision.envelope,\n      p_body_sha256: headers.bodySha256,\n      p_native_proof: nativeProof,\n    })\n    if (error || !ack || typeof ack !== 'object' || ack.envelopeId !== decision.envelope.envelopeId) {\n      return failure('INGEST_UNAVAILABLE', 503)\n    }\n    return response(ack)\n  } catch (error) {\n    const code = error instanceof Error ? error.message : 'INGEST_UNAVAILABLE'\n    if (code.startsWith('S2S_') || code === 'INVALID_SIGNATURE') return failure('SIGNATURE_REJECTED', 401)\n    return failure('INGEST_UNAVAILABLE', 503)\n  }\n})\n",
  "signature.ts": "export const BILLING_S2S_SIGNATURE_VERSION = 'v2.1.2' as const;\nexport const BILLING_S2S_CLOCK_SKEW_MS = 300000;\nexport type BillingS2SAction = 'ingest_supply_usage' | 'proxy_billing_action';\nexport interface BillingSignedHeaders {\n  keyId: string;\n  sender: 'supply';\n  audience: 'hrm-billing';\n  action: BillingS2SAction;\n  timestamp: string;\n  nonce: string;\n  bodySha256: string;\n  signature: string;\n}\nexport interface BillingSigningScope {\n  keyId: string;\n  secret: Uint8Array;\n  companyId: string;\n  providerIssuer: 'https://auth.example.invalid';\n  providerWorkspaceId: string;\n  sourceWorkspaceId: string;\n  identityRevision: string;\n  actions: readonly BillingS2SAction[];\n  active: boolean;\n}\nexport interface BillingVerifiedSignature { scope: Omit<BillingSigningScope, 'secret'>; requestSentAt: string; bodySha256: string }\nexport type ClaimNonce = (keyId: string, nonce: string, expiresAt: string) => Promise<boolean>;\nconst encoder = new TextEncoder();\nfunction hex(bytes: Uint8Array): string { return [...bytes].map(b => b.toString(16).padStart(2, '0')).join(''); }\nfunction base64url(bytes: Uint8Array): string { return btoa(String.fromCharCode(...bytes)).replace(/\\+/g, '-').replace(/\\//g, '_').replace(/=+$/g, ''); }\nfunction decodeBase64url(value: string): Uint8Array {\n  if (!/^[A-Za-z0-9_-]+$/.test(value)) throw new Error('INVALID_SIGNATURE');\n  const raw = atob(value.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - value.length % 4) % 4));\n  return Uint8Array.from(raw, c => c.charCodeAt(0));\n}\nexport async function sha256Body(rawUtf8Body: string): Promise<string> {\n  return hex(new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(rawUtf8Body))));\n}\nfunction canonical(headers: Omit<BillingSignedHeaders, 'signature'>): string {\n  return [BILLING_S2S_SIGNATURE_VERSION, headers.keyId, headers.sender, headers.audience, headers.action,\n    headers.timestamp, headers.nonce, headers.bodySha256].join('\\n');\n}\nasync function hmacKey(secret: Uint8Array): Promise<CryptoKey> {\n  if (secret.byteLength < 32) throw new Error('WEAK_S2S_KEY');\n  return crypto.subtle.importKey('raw', secret as BufferSource, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign', 'verify']);\n}\nexport async function signBillingRequest(rawUtf8Body: string, unsigned: Omit<BillingSignedHeaders, 'signature' | 'bodySha256'>, secret: Uint8Array): Promise<BillingSignedHeaders> {\n  const bodySha256 = await sha256Body(rawUtf8Body);\n  const fields = { ...unsigned, bodySha256 };\n  const signature = base64url(new Uint8Array(await crypto.subtle.sign('HMAC', await hmacKey(secret), encoder.encode(canonical(fields)))));\n  return { ...fields, signature };\n}\nexport async function verifyBillingRequest(rawUtf8Body: string, headers: BillingSignedHeaders, now: string,\n  lookupKey: (keyId: string) => Promise<BillingSigningScope | null>, claimNonce: ClaimNonce): Promise<BillingVerifiedSignature> {\n  const at = Date.parse(now), sent = Date.parse(headers.timestamp);\n  if (!Number.isFinite(at) || !Number.isFinite(sent) || Math.abs(at - sent) > BILLING_S2S_CLOCK_SKEW_MS) throw new Error('S2S_TIMESTAMP_EXPIRED');\n  if (!/^[A-Za-z0-9_-]{22,128}$/.test(headers.nonce) || !headers.keyId || headers.sender !== 'supply'\n    || headers.audience !== 'hrm-billing' || !['ingest_supply_usage', 'proxy_billing_action'].includes(headers.action)) throw new Error('S2S_HEADER_INVALID');\n  const scope = await lookupKey(headers.keyId);\n  if (!scope?.active || scope.keyId !== headers.keyId || !scope.actions.includes(headers.action)) throw new Error('S2S_KEY_SCOPE_DENIED');\n  const digest = await sha256Body(rawUtf8Body);\n  if (digest !== headers.bodySha256) throw new Error('S2S_BODY_MISMATCH');\n  const fields = { keyId: headers.keyId, sender: headers.sender, audience: headers.audience, action: headers.action,\n    timestamp: headers.timestamp, nonce: headers.nonce, bodySha256: headers.bodySha256 };\n  const verified = await crypto.subtle.verify('HMAC', await hmacKey(scope.secret), decodeBase64url(headers.signature) as BufferSource, encoder.encode(canonical(fields)));\n  if (!verified) throw new Error('S2S_SIGNATURE_INVALID');\n  const expiresAt = new Date(sent + BILLING_S2S_CLOCK_SKEW_MS).toISOString();\n  if (!await claimNonce(headers.keyId, headers.nonce, expiresAt)) throw new Error('S2S_NONCE_REPLAY');\n  const { secret: _secret, ...verifiedScope } = scope;\n  return { scope: verifiedScope, requestSentAt: headers.timestamp, bodySha256: digest };\n}\n"
};

const materialFixturePaths={'receiver.ts':'supabase/functions/billing-supply-ingest/index.ts','signature.ts':'supabase/functions/_shared/billing-signature.ts','resolver.sql':'supabase/migrations/scoped.sql','transport.sql':'supabase/migrations/transport.sql'};
function sqlFixture(t,change={}){
  const f=fixture(t),file='test/scoped.pg.sql';
  for(const [name,value] of Object.entries(sqlMaterialSources)){const target=join(f.repo,materialFixturePaths[name]??name);mkdirSync(resolve(target,'..'),{recursive:true});writeFileSync(target,change[name]??value);}
  command(f.repo,['add','.']);command(f.repo,['commit','-qm','actual public SQL material role fixtures']);
  f.options.head=f.decision.head=command(f.repo,['rev-parse','HEAD']);
  const lines=readFileSync(join(f.repo,file),'utf8').split('\n');
  const envLine=lines.findIndex(v=>/^\s*config:='/.test(v))+1;
  const config=JSON.parse(/config:='(.*)';/.exec(lines[envLine-1])[1]);
  const secret=config.binding.secretRef??config.binding.secretBytes;
  const nonceValue=/billing_claim_transport_nonce\(old_key,'(nonce-[a-z0-9-]+)'/.exec(lines.join('\n'))?.[1]??'nonce-a-scoped-123456789012';
  const nonceLines=lines.map((v,i)=>v.includes("'"+nonceValue+"'")?i+1:0).filter(Boolean);
  const items=[{line:envLine,value:secret,classification:'sql_environment_reference'},...nonceLines.map(line=>({line,value:nonceValue,classification:'sql_rollback_replay_nonce'}))];
  const raw=items.map((item,index)=>({File:file,StartLine:item.line,Secret:item.value,RuleID:'generic-api-key',Fingerprint:`${file}:generic-api-key:${index}`}));
  writeFileSync(f.reportPath,JSON.stringify(raw));f.options.reportSha256=f.decision.report_sha256=sha(readFileSync(f.reportPath));
  f.decision.findings=items.map((item,index)=>({reportIndex:index,fingerprint:raw[index].Fingerprint,finding_sha256:secretFindingHash(raw[index]),...f.binding(file,item.line),blob_oid:command(f.repo,['rev-parse',`${f.options.head}:${file}`]),classification:item.classification,rationale:'Exact source-backed active reference or replay-ledger role in rollback-only native SQL.',evidence:['resolver.sql','transport.sql','receiver.ts','signature.ts'].map(name=>f.binding(materialFixturePaths[name]??name))}));
  return f;
}
test('three actual SQL fixture rows have structurally proved non-signing roles; no review approval or raw rewrite',t=>{
  const f=sqlFixture(t),before=readFileSync(f.reportPath),result=f.check();
  assert.equal(result.status,'pass');assert.equal(result.findings.length,3);assert.ok(result.findings.every(r=>r.applicable&&!r.blocking));assert.deepEqual(readFileSync(f.reportPath),before);assert.equal(result.review,undefined);
  assert.throws(()=>verifySecretAdjudication(f.options),/INDEPENDENT_PROOF_REQUIRED/);
});
test('SQL reference names and replay nonce values are parameterized, never an allowlist of current literals',t=>{
  const data={...sqlMaterialSources};
  data['test/scoped.pg.sql']=data['test/scoped.pg.sql'].replaceAll('BILLING_S2S_KEY_SCOPED_BINDING','BILLING_S2S_KEY_ANOTHER_REFERENCE').replaceAll('nonce-a-scoped-123456789012','nonce-another-valid-1234567890');
  const f=sqlFixture(t,data);
  assert.equal(f.decision.findings.length,3);assert.equal(f.check().status,'pass');
});
