test('nonce claim second argument, opposite assertion, independent key and ledger consumer are mandatory',t=>{
  const changes=[
    {'test/scoped.pg.sql':sqlMaterialSources['test/scoped.pg.sql'].replace('IF NOT billing_claim_transport_nonce(old_key','IF billing_claim_transport_nonce(old_key')},
    {'test/scoped.pg.sql':sqlMaterialSources['test/scoped.pg.sql'].replace('OR billing_claim_transport_nonce(old_key','OR NOT billing_claim_transport_nonce(old_key')},
    {'test/scoped.pg.sql':sqlMaterialSources['test/scoped.pg.sql'].replace("OR billing_claim_transport_nonce(old_key,'nonce-a-scoped-123456789012'","OR billing_claim_transport_nonce(old_key,'nonce-other-scoped-123456789012'")},
    {'test/scoped.pg.sql':sqlMaterialSources['test/scoped.pg.sql'].replaceAll("old_key,'nonce-a-scoped-123456789012'","'nonce-a-scoped-123456789012',old_key")},
    {'test/scoped.pg.sql':sqlMaterialSources['test/scoped.pg.sql'].replace('old_key:=billing_supply_scoped_transport_id','old_key:=unknown_signing_material')},
    {'test/scoped.pg.sql':sqlMaterialSources['test/scoped.pg.sql'].replace('  changed:=',"  PERFORM sign('nonce-a-scoped-123456789012');\n  changed:=")},
    {'test/scoped.pg.sql':sqlMaterialSources['test/scoped.pg.sql'].replace('  changed:=',"  EXECUTE 'SELECT sign(''nonce-a-scoped-123456789012'')';\n  changed:=")},
    {'transport.sql':sqlMaterialSources['transport.sql'].replace('VALUES(p_key_id,p_nonce,p_body_sha256','VALUES(p_nonce,p_key_id,p_body_sha256')},
    {'transport.sql':sqlMaterialSources['transport.sql'].replace('DECLARE inserted integer;','DECLARE inserted integer;\n-- lookalike nonce ledger below\n/*').replace('RETURN inserted=1;','RETURN inserted=1; */')},
    {'transport.sql':sqlMaterialSources['transport.sql'].replace('RETURN inserted=1;','PERFORM sign(p_nonce); RETURN inserted=1;')},
    {'resolver.sql':sqlMaterialSources['resolver.sql'].replace("RETURN 'p1_'","RETURN 'secret'")},
  ];
  for(const change of changes){const f=sqlFixture(t,change);const result=f.check();assert.ok(result.findings.some(r=>r.classification==='sql_rollback_replay_nonce'));assert.ok(result.findings.filter(r=>r.classification==='sql_rollback_replay_nonce').every(r=>r.blocking),JSON.stringify(Object.keys(change)));}
});
test('SQL categories retain exact report/evidence coverage and forged-proof denial',t=>{
  for(const change of [f=>f.decision.findings[0].evidence=[],f=>f.decision.findings[0].evidence[0].line_sha256='0'.repeat(64),f=>f.decision.findings[0].oracle={status:'pass'},f=>f.decision.findings[0].finding_sha256='0'.repeat(64)]){
    const f=sqlFixture(t);change(f);if(!f.decision.findings[0].evidence.length||f.decision.findings[0].oracle)assert.equal(f.check().status,'fail');else assert.throws(f.check,/ADJUDICATION_/);
  }
  const f=sqlFixture(t),proof=join(f.repo,'unapproved-sql-proof.json');writeFileSync(proof,JSON.stringify({approved:true,verdict:'PASS'}));assert.throws(()=>verifySecretAdjudication({...f.options,proofPath:proof}),/TEAMQA_|ADJUDICATION_/);
});

test('active template interpolation cannot hide unknown receiver signing execution',t=>{
  const f=sqlFixture(t,{'receiver.ts':sqlMaterialSources['receiver.ts']+'\nconst hidden = `${eval("unknown signing execution")}`;\n'});
  assert.equal(f.check().findings[0].blocking,true);
});
test('lowercase DO cannot hide dynamic SQL signing material inside rollback fixture',t=>{
  const f=sqlFixture(t,{'test/scoped.pg.sql':sqlMaterialSources['test/scoped.pg.sql'].replace(/ROLLBACK;\s*$/, "do $hidden$ BEGIN EXECUTE 'SELECT sign(''nonce-a-scoped-123456789012'')'; END; $hidden$;\nROLLBACK;")});
  const rows=f.check().findings; assert.ok(rows.length>=3); assert.ok(rows.every(r=>r.blocking));
});
test('receiver binding cannot shadow the actual imported verification consumer',t=>{
  const f=sqlFixture(t,{'receiver.ts':sqlMaterialSources['receiver.ts'].replace('  try {\n    const verified','  const verifyBillingRequest = async () => ({scope:{}})\n  try {\n    const verified')});
  assert.equal(f.check().findings[0].blocking,true);
});

test('aggregation helper rejects an unverified effective override',()=>{
  assert.throws(()=>verifiedSecretStatus({status:'pass',layers:{secret:{status:'fail',effective_status:'pass',raw_scanner:{status:'fail'},adjudication:{status:'pass'}}}}),/ADJUDICATION_/);
  assert.equal(verifiedSecretStatus({status:'fail',layers:{secret:{status:'fail'}}}),'fail');
});
